widths=1.2, zorder=5)\n    elif mode == 'con':\n        ax.scatter(x, y, marker='o', s=60, c=COLOR_CON, edgecolors=COLOR_CON,\n                   linewidths=1.2, zorder=4)\n    else:\n        ax.scatter(x, y, marker='o', s=60, facecolors='none', edgecolors=COLOR_UNC,\n                   linewidths=1.5, zorder=4)\n\n# Annotations with manual offsets to avoid overlap\noffsets = {\n    'k1_unc': (-6, -14),\n    'k1_con': (-6, 7),\n    'k2_unc': (7, 4),\n    'k2_con': (8, -10),\n    'k4_unc': (-6, -14),\n    'k4_con': (7, 4),\n    'k8_unc': (-6, -14),\n    'k8_con': (7, 4),\n}\n\nfor key, d in data.items():\n    x = d['latency'] / baseline_latency\n    y = d['R_F1']\n    k = d['k']\n    ox, oy = offsets[key]\n    ax.annotate(f'k={k}', (x, y), textcoords='offset points', xytext=(ox, oy),\n                fontsize=8.5, color='#333333')\n\n# Pareto optimal annotation with arrow\nk2c = data['k2_con']\nx_k2c = k2c['latency'] / baseline_latency\ny_k2c = k2c['R_F1']\nax.annotate('Pareto\\noptimal', (x_k2c, y_k2c),\n            textcoords='offset points', xytext=(30, 10),\n            fontsize=8.5, fontweight='bold', color=COLOR_CON,\n            arrowprops=dict(arrowstyle='->', color=COLOR_CON, lw=1.2),\n            ha='center')\n\n# Connect points by mode with dashed lines\nfor mode, color, ls in [('unc', COLOR_UNC, '--'), ('con', COLOR_CON, '-')]:\n    pts = [(d['latency'] / baseline_latency, d['R_F1'])\n           for d in sorted([v for v in data.values() if v['mode'] == mode], key=lambda v: v['k'])]\n    xs, ys = zip(*pts)\n    ax.plot(xs, ys, color=color, ls=ls, lw=1.0, alpha=0.45, zorder=2)\n\n# Legend\nfrom matplotlib.lines import Line2D\nlegend_elements = [\n    Line2D([0], [0], marker='o', color='w', markerfacecolor=COLOR_CON,\n           markeredgecolor=COLOR_CON, markersize=8, label='Constrained (DR=0%)'),\n    Line2D([0], [0], marker='o', color='w', markerfacecolor='none',\n           markeredgecolor=COLOR_UNC, markersize=8, markeredgewidth=1.5,\n           label='Unconstrained'),\n]\nax.legend(handles=legend_elements, loc='lower right', frameon=True,\n          edgecolor='#cccccc', fancybox=False)\n\nax.set_xlabel('Relative Latency (×baseline)')\nax.set_ylabel('Relation F1')\n\noutdir = '/root/autodl-tmp/schema_outputs/d066_beam_sweep/figures'\nfig.savefig(f'{outdir}/beam_pareto.pdf')\nfig.savefig(f'{outdir}/beam_pareto.png')\nplt.close()\nprint('Saved beam_pareto.pdf and beam_pareto.png')\nPYEOF"},"caller":{"type":"direct"}}],"stop_reason":null,"stop_sequence":null,"stop_details":null,"usage":{"input_tokens":1,"cache_creation_input_tokens":232,"cache_read_input_tokens":26040,"cache_creation":{"ephemeral_5m_input_tokens":0,"ephemeral_1h_input_tokens":232},"output_tokens":64,"service_tier":"standard","inference_geo":"not_available"},"diagnostics":null,"context_management":null},"parent_tool_use_id":null,"session_id":"fdf6f0db-8215-452b-93af-9718d0a30473","uuid":"33e1987b-b0d3-4d7d-a1d3-b77da3dfbc87"}
